"use client";

import {
  motion,
  useMotionValue,
  useReducedMotion,
  useSpring,
} from "framer-motion";
import type { PointerEvent, ReactNode } from "react";

import { SPRING_MOUSE } from "@/lib/ease";
import { useHoverCapable } from "@/lib/hooks/use-hover-capable";
import { cn } from "@/lib/utils";

export interface MagneticProps {
  children: ReactNode;
  className?: string;
  /** Fraction of the pointer distance the element travels toward the cursor (0-1). Default 0.35. */
  strength?: number;
  /** Maximum travel distance in px from the rest position. Default 32. */
  maxOffset?: number;
  /** Scale applied while the pointer is inside the element. Default 1.04. */
  hoverScale?: number;
}

const clamp = (value: number, min: number, max: number) =>
  Math.min(Math.max(value, min), max);

export const Magnetic = ({
  children,
  className,
  strength = 0.35,
  maxOffset = 32,
  hoverScale = 1.04,
}: MagneticProps) => {
  const reduce = useReducedMotion();
  const canHover = useHoverCapable();

  const offsetX = useMotionValue(0);
  const offsetY = useMotionValue(0);
  const x = useSpring(offsetX, SPRING_MOUSE);
  const y = useSpring(offsetY, SPRING_MOUSE);
  const scale = useSpring(1, { damping: 22, mass: 0.4, stiffness: 320 });

  const pull = (event: PointerEvent<HTMLDivElement>) => {
    if (!canHover || reduce) {
      return;
    }
    const rect = event.currentTarget.getBoundingClientRect();
    const dx = event.clientX - (rect.left + rect.width / 2);
    const dy = event.clientY - (rect.top + rect.height / 2);
    offsetX.set(clamp(dx * strength, -maxOffset, maxOffset));
    offsetY.set(clamp(dy * strength, -maxOffset, maxOffset));
  };

  const release = () => {
    offsetX.set(0);
    offsetY.set(0);
    scale.set(1);
  };

  return (
    <motion.div
      className={cn("inline-block", className)}
      style={{ scale, x, y }}
      onPointerEnter={() => {
        if (!canHover || reduce) {
          return;
        }
        scale.set(hoverScale);
      }}
      onPointerMove={pull}
      onPointerLeave={release}
      onPointerCancel={release}
    >
      {children}
    </motion.div>
  );
};

export default Magnetic;

// Shared motion tokens. Easing curves mirror the CSS custom properties in
// globals.css; springs are the canonical physics used across components.
// Strong custom variants — defaults like `ease-in`/`ease-out` feel weak.

export const EASE_OUT = [0.16, 1, 0.3, 1] as const;
export const EASE_IN_OUT = [0.77, 0, 0.175, 1] as const;
export const EASE_DRAWER = [0.32, 0.72, 0, 1] as const;

/** CSS string form of EASE_OUT for inline style transitions. */
export const EASE_OUT_CSS = "cubic-bezier(0.16, 1, 0.3, 1)";

/** Press feedback on buttons and other tappable surfaces. */
export const SPRING_PRESS = {
  damping: 30,
  mass: 0.6,
  stiffness: 500,
  type: "spring",
} as const;

/** Content swaps — label/icon slots trading places inside a control. */
export const SPRING_SWAP = {
  damping: 30,
  mass: 0.55,
  stiffness: 460,
  type: "spring",
} as const;

/** Overlay panel entrances — modals and sheets summoned by pointer. */
export const SPRING_PANEL = {
  damping: 40,
  mass: 0.5,
  stiffness: 420,
  type: "spring",
} as const;

/** Shared-layout glides — pills, indicators and panels morphing between positions. */
export const SPRING_LAYOUT = {
  damping: 32,
  mass: 0.6,
  stiffness: 360,
  type: "spring",
} as const;

/** Cursor-follow physics for decorative mouse tracking (magnetic, tilt, dock). */
export const SPRING_MOUSE = {
  damping: 20,
  mass: 0.5,
  stiffness: 280,
} as const;

"use client";

import { useEffect, useState } from "react";

/**
 * Returns true only on devices that have a true hover (mouse / trackpad).
 * Touch devices fire phantom `:hover` on tap that sticks until tap-elsewhere
 * — gate hover-only effects (scale lifts, magnetic pulls) behind this.
 */
export const useHoverCapable = () => {
  const [canHover, setCanHover] = useState(false);

  useEffect(() => {
    if (typeof window === "undefined" || !window.matchMedia) {
      return;
    }
    const mq = window.matchMedia("(hover: hover) and (pointer: fine)");
    const update = () => setCanHover(mq.matches);
    update();
    mq.addEventListener?.("change", update);
    return () => mq.removeEventListener?.("change", update);
  }, []);

  return canHover;
};
